
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_7_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_7", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.905604114306271e+00, -4.808168725261117e+00, -4.671590098562886e+00, -4.482281019229457e+00, -4.224041486693773e+00, -3.879603589041843e+00, -3.434197578512187e+00, -2.881228627042483e+00, -2.228693176345395e+00, -1.519805588765473e+00, -9.170894444382908e-01, -6.495178112099510e-01, -6.221185676903385e-01, -5.277283689699636e-01, -3.636844054514777e-01, -2.044262535864185e-01, -9.141650482919599e-02, -3.043497857574994e-02, -6.538888927095070e-03, -7.358917184239691e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


